// Nó: Code (JavaScript) — n8n | Fluxo 1.2
// Lê a planilha com duas tabelas lado a lado (INTERIOR | CAPITAL)
// Layout: A-I = INTERIOR | J = separador | K-S = CAPITAL
// Colunas de cada bloco: CLIENTE | (lado) | ACIMA DE | KG LIMITE | KG EXCEDENTE |
//                        FRETE MINIMO | SEGURO | GRIS | TABELA

const rows = $input.all().map(item => item.json);

// ─────────────────────────────────────────────────────────────
// 1. Localiza a linha de cabeçalho real da planilha
// ─────────────────────────────────────────────────────────────
const headerRow = rows.find(r =>
  Object.values(r).some(v => String(v ?? '').trim().toUpperCase() === 'INTERIOR')
);

if (!headerRow) {
  throw new Error('Cabeçalho não encontrado. Verifique o formato da planilha.');
}

// ─────────────────────────────────────────────────────────────
// 2. Mapeia as chaves do n8n em ordem posicional
// ─────────────────────────────────────────────────────────────
const todasAsChaves = Object.keys(headerRow);

const idxInterior = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'INTERIOR'
);
const idxCapital = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'CAPITAL'
);

if (idxInterior === -1 || idxCapital === -1) {
  throw new Error('Colunas INTERIOR ou CAPITAL não encontradas no cabeçalho.');
}

const idxClienteInterior = idxInterior - 1;
const idxClienteCapital  = idxCapital  - 1;

const chavesInterior = todasAsChaves.slice(idxClienteInterior, idxCapital - 1);
const chavesCapital  = todasAsChaves.slice(idxClienteCapital);

function montarMapa(chaves) {
  const mapa = {};
  for (const chave of chaves) {
    const nome = String(headerRow[chave] ?? '').trim().toUpperCase();
    if (nome !== '') mapa[nome] = chave;
  }
  return mapa;
}

const mapaInterior = montarMapa(chavesInterior);
const mapaCapital  = montarMapa(chavesCapital);

// ─────────────────────────────────────────────────────────────
// 3. Funções de normalização
// ─────────────────────────────────────────────────────────────
function normalizarTaxa(raw) {
  if (typeof raw === 'string' && raw.includes('%'))
    return parseFloat(raw.replace('%', '').replace(',', '.').trim()) / 100;
  return parseFloat(raw) || 0;
}

function normalizarAcimaDe(raw) {
  if (typeof raw === 'string' && raw.toUpperCase().includes('TODAS')) return 'TODAS';
  return parseFloat(raw) || 0;
}

function normalizarKg(raw) {
  if (typeof raw === 'string') return parseFloat(raw.replace(/[^0-9.]/g, '')) || 0;
  return parseFloat(raw) || 0;
}

// Lê a coluna TABELA e extrai o acréscimo de imposto.
// O número NUNCA fica cravado aqui — sai sempre do texto da planilha.
// Padrão esperado: "SOMAR 23,93% SOBRE O CTE (VALOR FINAL) (IMPOSTOS)"
function extrairAcrescimo(texto) {
  const m = String(texto ?? '').match(/SOMAR\s+([\d.,]+)\s*%/i);
  if (!m) return 0;
  const pct = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
  if (!isFinite(pct) || pct <= 0) return 0;
  return pct / 100;
}

// ─────────────────────────────────────────────────────────────
// 4. Parser — lê apenas as colunas do lado correto
// ─────────────────────────────────────────────────────────────
const CAMPOS_FIXOS = ['CLIENTE', 'INTERIOR', 'CAPITAL', 'ACIMA DE', 'KG LIMITE',
                      'KG EXCEDENTE', 'FRETE MINIMO', 'SEGURO', 'GRIS', 'TABELA'];

function parsearCliente(row, mapa, colunaLado) {
  const chaveNome   = mapa['CLIENTE']  ?? mapa[colunaLado];
  const chaveTaxa   = mapa[colunaLado];
  const chaveAcima  = mapa['ACIMA DE'];
  const chaveKgLim  = mapa['KG LIMITE'];
  const chaveKgExc  = mapa['KG EXCEDENTE'];
  const chaveFrete  = mapa['FRETE MINIMO'];
  const chaveSeguro = mapa['SEGURO'];
  const chaveGris   = mapa['GRIS'];
  const chaveTabela = mapa['TABELA'];

  const nome = row[chaveNome];
  if (!nome || String(nome).trim() === '' || String(nome).trim().toUpperCase() === 'CLIENTE') return null;

  const obsTabela = String(row[chaveTabela] ?? '').trim();
  const semTabela = obsTabela.toUpperCase() === 'SEM TABELA';

  const cliente = {
    cliente:           String(nome).trim(),
    taxa:              normalizarTaxa(row[chaveTaxa]),
    acima_de:          normalizarAcimaDe(row[chaveAcima]),
    kg_limite:         normalizarKg(row[chaveKgLim]),
    kg_excedente:      parseFloat(row[chaveKgExc]) || 0,
    frete_minimo:      parseFloat(row[chaveFrete])  || 0,
    seguro:            parseFloat(row[chaveSeguro]) || 0,
    gris:              parseFloat(row[chaveGris])   || 0,
    tabela:            obsTabela,
    sem_tabela:        semTabela,
    acrescimo_imposto: semTabela ? 0 : extrairAcrescimo(obsTabela),
  };

  // Alerta: observação preenchida que não é "SEM TABELA" e não casou com o padrão
  cliente.tabela_nao_reconhecida =
    obsTabela !== '' && !semTabela && cliente.acrescimo_imposto === 0;

  // Campos extras futuros (ICMS, PEDAGIO, etc.) — apenas do lado correto
  const chavesFixasSet = new Set(Object.values(
    Object.fromEntries(CAMPOS_FIXOS.map(n => [n, mapa[n]]).filter(([, v]) => v))
  ));
  for (const chave of Object.keys(mapa).map(n => mapa[n])) {
    if (chavesFixasSet.has(chave)) continue;
    const valor = row[chave];
    if (valor === null || valor === undefined || String(valor).trim() === '') continue;
    const nomeReal = String(headerRow[chave] ?? chave).trim().toLowerCase();
    const numero = parseFloat(valor);
    cliente[nomeReal] = isNaN(numero) ? String(valor).trim() : numero;
  }

  return cliente;
}

// ─────────────────────────────────────────────────────────────
// 5. Processa todas as linhas de dados
// ─────────────────────────────────────────────────────────────
const tabela = { INTERIOR: [], CAPITAL: [] };

for (const row of rows) {
  if (row === headerRow) continue;

  const interior = parsearCliente(row, mapaInterior, 'INTERIOR');
  if (interior) tabela.INTERIOR.push(interior);

  const capital = parsearCliente(row, mapaCapital, 'CAPITAL');
  if (capital) tabela.CAPITAL.push(capital);
}

// ─────────────────────────────────────────────────────────────
// 6. Diagnóstico — aparece na saída do nó para conferência
// ─────────────────────────────────────────────────────────────
const alertas = [];
for (const lado of ['INTERIOR', 'CAPITAL']) {
  for (const c of tabela[lado]) {
    if (c.tabela_nao_reconhecida) {
      alertas.push(`${lado} | ${c.cliente} | observação não reconhecida na coluna TABELA: "${c.tabela}"`);
    }
  }
}

return [{
  json: {
    tabela_clientes: tabela,
    diagnostico: {
      total_interior: tabela.INTERIOR.length,
      total_capital:  tabela.CAPITAL.length,
      com_acrescimo:  [...tabela.INTERIOR, ...tabela.CAPITAL]
                        .filter(c => c.acrescimo_imposto > 0)
                        .map(c => `${c.cliente} (${(c.acrescimo_imposto * 100).toFixed(2)}%)`),
      sem_tabela:     [...new Set([...tabela.INTERIOR, ...tabela.CAPITAL]
                        .filter(c => c.sem_tabela).map(c => c.cliente))],
      alertas,
    }
  }
}];

// Nó: Code (JavaScript) — n8n | Fluxo 1.2
// Cálculo de frete (ad valorem + excedente) + leitura do acréscimo de imposto

// ===============================
// 🔹 Entrada
// ===============================
const entrada = $('Organiza dados1').first().json;
const tabela_clientes = $('Organiza a saída da tabela').first().json.tabela_clientes;

const cliente_nome_raw = String(entrada.cliente || '').trim();
const cliente_nome     = cliente_nome_raw.toUpperCase();

const tipo_tabela      = String(entrada.tipo_tabela || 'INTERIOR').toUpperCase();

const parseMoeda = (valor) => {
  const str = String(valor || '0').replace(/[^\d.,]/g, '');

  if (/\d+\.\d{3},\d{2}$/.test(str)) {
    return Number(str.replace(/\./g, '').replace(',', '.')) || 0;
  }
  if (/^\d+\.\d+$/.test(str)) {
    return Number(str) || 0;
  }
  if (/^\d+,\d+$/.test(str)) {
    return Number(str.replace(',', '.')) || 0;
  }
  return Number(str) || 0;
};

const valor_mercadoria = parseMoeda(entrada.valor_mercadoria);
const peso_informado   = parseMoeda(entrada.peso);
const dedicado         = String(entrada.dedicado || 'nao').toLowerCase().trim();

const lista = tabela_clientes?.[tipo_tabela] || [];

// ===============================
// 🔴 REGRA: CLIENTE AVULSO
// ===============================
if (cliente_nome === "AVULSO") {
  if (dedicado === "sim") {
    return [{
      json: {
        cliente: "AVULSO",
        tipo_tabela,
        peso_informado: 0,
        peso_considerado: 0,
        valor_mercadoria: Number(valor_mercadoria.toFixed(2)),
        frete_ad_valorem: 0,
        seguro_valor: 0,
        gris_valor: 0,
        frete_base: 0,
        tem_excedente: false,
        excedente: 0,
        frete_final: 0,
        acrescimo_imposto: 0,
        dedicado: "sim",
        perfil_cliente: "A",
        observacao: "Cliente avulso - frete dedicado tratado fora"
      }
    }];
  }
  return [{ json: { erro_frete: "Cliente AVULSO sem frete dedicado.", tipo_erro: "avulso_sem_dedicado" } }];
}

// ===============================
// 🔹 Normalização
// ===============================
const normalizar = (str) => {
  return String(str || '')
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\b(ltda|me|epp|sa|s\/a)\b/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const nomeEntrada = normalizar(cliente_nome_raw);

// ===============================
// 🔹 Similaridade
// ===============================
const scoreSimilaridade = (a, b) => {
  const palavrasA = a.split(' ');
  const palavrasB = b.split(' ');
  let match = 0;
  for (const p of palavrasA) {
    if (palavrasB.includes(p)) match++;
  }
  return match / Math.max(palavrasA.length, palavrasB.length);
};

const SCORE_MINIMO = 0.34;

// ===============================
// 🔹 ETAPA 1 — MATCH EXATO POR REDUÇÃO
// ===============================
let cliente = null;
let melhorScore = 1;
let candidatos = [];
const partes = nomeEntrada.split(' ');

for (let i = partes.length; i > 0; i--) {
  const tentativa = partes.slice(0, i).join(' ');
  const achado = lista.find(c => normalizar(c.cliente) === tentativa);
  if (achado) { cliente = achado; break; }
}

// ===============================
// 🔹 ETAPA 2 — PREFIXO / INCLUSÃO
// ===============================
if (!cliente) {
  candidatos = lista.filter(c => {
    const nomeTabela = normalizar(c.cliente);
    return nomeTabela.startsWith(nomeEntrada) || nomeEntrada.includes(nomeTabela);
  });
  if (candidatos.length === 1) cliente = candidatos[0];
}

// ===============================
// 🔹 ETAPA 3 — SCORE DE SIMILARIDADE
// ===============================
if (!cliente && candidatos.length === 0) {
  melhorScore = 0;
  for (const c of lista) {
    const score = scoreSimilaridade(nomeEntrada, normalizar(c.cliente));
    if (score > melhorScore) { melhorScore = score; candidatos = [c]; }
    else if (score === melhorScore && score > 0) { candidatos.push(c); }
  }
  if (melhorScore >= SCORE_MINIMO && candidatos.length === 1) {
    cliente = candidatos[0];
  }
}

// ===============================
// 🔴 SEM FALLBACK CEGO
// Antes o código pegava lista[0] quando não achava, o que devolvia a tabela
// da ABIV para qualquer nome desconhecido. Agora retorna erro.
// ===============================
if (!cliente) {
  if (candidatos.length > 1) {
    return [{
      json: {
        erro_frete: "Mais de um cliente da tabela corresponde ao nome informado.",
        tipo_erro: "cliente_ambiguo",
        cliente_original: cliente_nome_raw,
        tipo_tabela,
        opcoes: candidatos.map(c => c.cliente),
      }
    }];
  }
  return [{
    json: {
      erro_frete: "Cliente não encontrado na tabela.",
      tipo_erro: "cliente_nao_encontrado",
      cliente_original: cliente_nome_raw,
      tipo_tabela,
    }
  }];
}

// ===============================
// 🔴 CLIENTE SEM TABELA COMERCIAL
// ===============================
if (cliente.sem_tabela === true) {
  return [{
    json: {
      erro_frete: "Cliente sem tabela comercial cadastrada.",
      tipo_erro: "cliente_sem_tabela",
      cliente: cliente.cliente,
      cliente_original: cliente_nome_raw,
      tipo_tabela,
    }
  }];
}

// ===============================
// 🔹 Peso considerado
// ===============================
const peso_taxado_final = Number($('Sugestão de veículo1').first().json.peso_considerado || 0);
const peso_considerado  = Math.max(peso_informado, peso_taxado_final);

// ===============================
// 🔹 Identificação do perfil e cálculo do frete
// PERFIL A: taxa > 0, sem seguro/gris
// PERFIL B: taxa = 0, com seguro e/ou gris
// PERFIL C: taxa > 0, com seguro e/ou gris
// ===============================

const taxa         = cliente.taxa         || 0;
const seguro       = cliente.seguro       || 0;
const gris         = cliente.gris         || 0;
const frete_minimo = cliente.frete_minimo || 0;

const tem_seguro_gris = (seguro + gris) > 0;
const tem_taxa        = taxa > 0;

let perfil_cliente;
let frete_ad_valorem = 0;
let seguro_valor     = 0;
let gris_valor       = 0;
let frete_base       = 0;

if (tem_taxa && !tem_seguro_gris) {
  // ── PERFIL A ──
  perfil_cliente   = "A";
  frete_ad_valorem = valor_mercadoria * taxa;
  frete_base       = Math.max(frete_ad_valorem, frete_minimo);

} else if (!tem_taxa && tem_seguro_gris) {
  // ── PERFIL B ──
  perfil_cliente = "B";
  seguro_valor   = valor_mercadoria * seguro;
  gris_valor     = valor_mercadoria * gris;
  frete_base     = frete_minimo + seguro_valor + gris_valor;

} else if (tem_taxa && tem_seguro_gris) {
  // ── PERFIL C ──
  perfil_cliente   = "C";
  frete_ad_valorem = valor_mercadoria * taxa;

  if (frete_ad_valorem > frete_minimo) {
    frete_base = frete_ad_valorem;
  } else {
    seguro_valor = valor_mercadoria * seguro;
    gris_valor   = valor_mercadoria * gris;
    frete_base   = frete_minimo + seguro_valor + gris_valor;
  }

} else {
  // edge case: sem taxa e sem seguro/gris
  perfil_cliente = "A";
  frete_base     = frete_minimo;
}

// ===============================
// 🔹 Excedente de peso
// ===============================
let excedente     = 0;
let tem_excedente = false;

if (cliente.kg_limite > 0 && cliente.acima_de !== 'TODAS') {
  if (peso_considerado > cliente.kg_limite) {
    excedente     = (peso_considerado - cliente.kg_limite) * cliente.kg_excedente;
    tem_excedente = true;
  }
}

const frete_final = frete_base + excedente;

// ===============================
// 🔹 Acréscimo de imposto (ES) — valor vem da coluna TABELA da planilha
// A aplicação acontece no nó final, sobre o valor total.
// ===============================
const acrescimo_imposto = Number(cliente.acrescimo_imposto || 0);

// ===============================
// 🔹 Retorno
// ===============================
return [{
  json: {
    cliente:            cliente.cliente,
    cliente_original:   cliente_nome_raw,
    tipo_tabela,
    taxa_aplicada:      taxa,
    frete_minimo,
    kg_limite:          cliente.kg_limite,
    kg_excedente_valor: cliente.kg_excedente,
    acima_de:           String(cliente.acima_de),
    seguro_taxa:        seguro,
    gris_taxa:          gris,
    peso_informado:     Number(peso_informado.toFixed(2)),
    peso_considerado:   Number(peso_considerado.toFixed(2)),
    valor_mercadoria:   Number(valor_mercadoria.toFixed(2)),
    frete_ad_valorem:   Number(frete_ad_valorem.toFixed(2)),
    seguro_valor:       Number(seguro_valor.toFixed(2)),
    gris_valor:         Number(gris_valor.toFixed(2)),
    frete_base:         Number(frete_base.toFixed(2)),
    tem_excedente,
    excedente:          Number(excedente.toFixed(2)),
    frete_final:        Number(frete_final.toFixed(2)),
    acrescimo_imposto,
    observacao_tabela:  cliente.tabela || '',
    dedicado,
    perfil_cliente,
    score_match:        Number(melhorScore.toFixed(2))
  }
}];

// Nó: Code (JavaScript) — n8n | Fluxo 1.2
// Consolida todos os dados para retorno ao agente e aplica o acréscimo de imposto

const rota  = $('Cálculo final (imposto)1').first().json;
const frete = $('Cálculo de frete (ad valorem + excedente)').first().json;

// ===============================
// 🔴 Erros vindos do cálculo de frete
// ===============================
if (frete.erro_frete) {
  return [{
    json: {
      erro_frete:       frete.erro_frete,
      tipo_erro:        frete.tipo_erro || 'desconhecido',
      cliente:          frete.cliente || null,
      cliente_original: frete.cliente_original || null,
      tipo_tabela:      frete.tipo_tabela || null,
      opcoes:           frete.opcoes || [],
    }
  }];
}

const eh_dedicado             = frete.dedicado === 'sim';
const custo_total_com_imposto = Number(rota.custo_total_com_imposto || 0);
const frete_final_valor       = Number(frete.frete_final || 0);

// ===============================
// 🔹 Valor total antes do acréscimo de imposto
// ===============================
const valor_total_sem_imposto = eh_dedicado
  ? frete_final_valor + custo_total_com_imposto
  : frete_final_valor;

// ===============================
// 🔹 Acréscimo de imposto (ES)
// Percentual lido da coluna TABELA da planilha. Incide sobre o valor total,
// já incluindo o custo de rota quando a cotação for dedicada.
// ===============================
const acrescimo_imposto     = Number(frete.acrescimo_imposto || 0);
const tem_acrescimo_imposto = acrescimo_imposto > 0;

// Arredonda o acréscimo ANTES de somar, para que a conta exibida na memória de
// cálculo (subtotal + acréscimo) bata exatamente com o total apresentado.
const acrescimo_imposto_valor =
  Number((valor_total_sem_imposto * acrescimo_imposto).toFixed(2));

// valor_total já sai COM o acréscimo aplicado.
// Para clientes sem acréscimo, é idêntico ao comportamento anterior.
const valor_total = Number(valor_total_sem_imposto.toFixed(2)) + acrescimo_imposto_valor;

return [{
  json: {
    distancia_km_ida_e_volta: rota.km_total,
    pedagios_ida_e_volta:     rota.pedagio_total,
    veiculo_sugerido:         $('Sugestão de veículo1').first().json.veiculo_sugerido,
    custo_combustivel:        rota.custo_combustivel,
    custo_total_base:         rota.custo_total_base,
    custo_total_com_imposto:  rota.custo_total_com_imposto,
    peso_informado:           frete.peso_informado,
    peso_taxado_final:        $('Sugestão de veículo1').first().json.peso_considerado,
    peso_considerado:         frete.peso_considerado,
    cliente:                  frete.cliente,
    tipo_tabela:              frete.tipo_tabela,
    taxa_aplicada:            frete.taxa_aplicada,
    frete_minimo:             frete.frete_minimo,
    kg_limite:                frete.kg_limite,
    kg_excedente_valor:       frete.kg_excedente_valor,
    acima_de:                 frete.acima_de,
    seguro_taxa:              frete.seguro_taxa,
    gris_taxa:                frete.gris_taxa,
    valor_mercadoria:         frete.valor_mercadoria,
    perfil_cliente:           frete.perfil_cliente,
    frete_ad_valorem:         frete.frete_ad_valorem,
    seguro_valor:             frete.seguro_valor,
    gris_valor:               frete.gris_valor,
    frete_base:               frete.frete_base,
    tem_excedente:            frete.tem_excedente,
    excedente:                frete.excedente,
    frete_final:              frete_final_valor,
    eh_dedicado,

    // ── Acréscimo de imposto (ES) ──
    tem_acrescimo_imposto,
    acrescimo_imposto_pct:    Number((acrescimo_imposto * 100).toFixed(2)),
    acrescimo_imposto_valor:  Number(acrescimo_imposto_valor.toFixed(2)),
    observacao_tabela:        frete.observacao_tabela || '',

    valor_total_sem_imposto:  Number(valor_total_sem_imposto.toFixed(2)),
    valor_total:              Number(valor_total.toFixed(2))
  }
}];
